"""Синтетические протоколы во всех известных форматах (без персональных данных).

Структура повторяет реальные протоколы горнолыжных стартов: титул с названием и датой, шапка,
строки-разделители групп, участники, пометки судьи справа.
"""

from __future__ import annotations

TITLE_ROWS = [
    ["Соревнования по горнолыжному спорту"],
    ["КУБОК ТЕСТОВОЙ ОБЛАСТИ"],
    ["Слалом-гигант, 15.02.2026, ГК «Тестовый склон»"],
    ["Предварительные результаты"],
    [],
]


def format_a_two_runs() -> dict[str, list[list[object]]]:
    """Формат A, два заезда: «Фамилия, Имя» одной колонкой, числовые времена и коды статусов."""
    header = ["Ст. №", "Фамилия, Имя", "Г.р.", "ФСО/клуб", "1 заезд", "2 заезд", "Результат", "Место", "Прим."]
    rows = [
        *TITLE_ROWS,
        header,
        ["Девочки 2014-2015 г.р."],
        [1, "Альфа Анна", 2014, "СШ Север", "35.10", "36.00", "71.10", 2, ""],
        [2, "Бета Вера", 2015, "СШ Юг", "34.50", "35.90", "70.40", 1, ""],
        [3, "Гамма Галина", 2014, "СШ Север", "100", "", "", "", ""],
        [4, "Дельта Дарья", 2015, "Клуб Восток", "36.20", "DNF", "", "", "DNF"],
        ["Мальчики 2014-2015 г.р."],
        [11, "Эпсилон Егор", 2014, "СШ Юг", "33.00", "", "", "", ""],
        [12, "Зета Захар", 2015, "СШ Север", "33.80", "", "", "", "касание флага"],
        [13, "Эта Эрик", 2014, "Клуб Восток", "1:02,5", "", "", "", ""],
        [14, "Тета Тимур", 2015, "СШ Юг", "", "", "", "", ""],
    ]
    return {"СЛГ": rows}


def format_a_lite_single_run() -> dict[str, list[list[object]]]:
    """Формат A-lite: один заезд, итог в следующей колонке."""
    header = ["Ст. №", "Фамилия, Имя", "ФСО", "1 трасса", "Итог"]
    rows = [
        ["ЗАКРЫТИЕ СЕЗОНА"],
        ["07 апреля 2026"],
        header,
        ["Девочки 2018 г.р. и младше"],
        [21, "Йота Ия", "СШ Север", "48.11", "48.11"],
        [22, "Каппа Ксения", "СШ Юг", "47.02", "47.02"],
        [23, "Лямбда Лиза", "СШ Север", "", ""],
    ]
    return {"Малыши": rows}


def format_b_split_names() -> dict[str, list[list[object]]]:
    """Формат B: «Старт номер», раздельные фамилия/имя, заезды во второй строке шапки, шапка повторяется."""
    head1 = ["Старт номер", "Фамилия", "Имя", "Команда", "Попытки", "", "Сумма"]
    head2 = ["", "", "", "", "1 трасса", "2 трасса", ""]
    rows = [
        ["ПЕРВЕНСТВО ТЕСТОВОЙ ОБЛАСТИ 02.04.26"],
        [],
        ["Юноши 2012-2013 г.р."],
        head1,
        head2,
        [31, "Мю", "Марк", "СШ Север", "40.00", "41.00", "81.00"],
        [32, "Ню", "Никита", "СШ Юг", "39.50", "", ""],
        ["Девушки 2012-2013 г.р."],
        head1,
        head2,
        [41, "Кси", "Ксения", "Клуб Восток", "", "", ""],
        [42, "Омикрон", "Ольга", "СШ Север", "", "", ""],
    ]
    return {"Слалом": rows}


def legacy_without_header() -> dict[str, list[list[object]]]:
    """Старый формат без распознаваемой шапки: колонки A–F начиная с 7-й строки."""
    rows = [
        ["Протокол"],
        [],
        [],
        [],
        [],
        ["№", "ФИО", "Команда", "Т1", "Т2", "Сумма"],
        ["Группа А"],
        [51, "Пи Павел", "СШ Юг", "30.00", "31.00", "61.00"],
        [52, "Ро Роман", "СШ Север", "29.00", "", ""],
    ]
    return {"Лист1": rows}
